<?php
/**
 * Registers the 'wpbp-content' ability category and the 'wpbp/count-words' ability.
 *
 * @package WPBP
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Register the ability category.
 */
add_action(
	'wp_abilities_api_categories_init',
	function () {
		if ( ! function_exists( 'wp_register_ability_category' ) ) {
			return;
		}

		wp_register_ability_category(
			'wpbp-content',
			array(
				'label'       => __( 'WPBP Content', 'wpbp' ),
				'description' => __( 'Content analysis and manipulation abilities provided by WPBP.', 'wpbp' ),
			)
		);
	}
);

/**
 * Register the ability.
 */
add_action(
	'wp_abilities_api_init',
	function () {
		if ( ! function_exists( 'wp_register_ability' ) ) {
			return;
		}

		wp_register_ability(
			'wpbp/count-words',
			array(
				'label'               => __( 'Count Words', 'wpbp' ),
				'description'         => __( 'Counts the number of words in the supplied text.', 'wpbp' ),
				'category'            => 'wpbp-content',
				'input_schema'        => array(
					'type'                 => 'object',
					'properties'           => array(
						'text' => array(
							'type'        => 'string',
							'description' => __( 'The text whose words should be counted.', 'wpbp' ),
						),
					),
					'required'             => array( 'text' ),
					'additionalProperties' => false,
				),
				'output_schema'       => array(
					'type'        => 'integer',
					'minimum'     => 0,
					'description' => __( 'The number of words found in the text.', 'wpbp' ),
				),
				'execute_callback'    => 'wpbp_count_words_ability_execute',
				'permission_callback' => 'wpbp_count_words_ability_permission',
				'meta'                => array(
					'show_in_rest' => true,
					'annotations'  => array(
						'readonly'    => true,
						'destructive' => false,
						'idempotent'  => true,
					),
				),
			)
		);
	}
);

/**
 * Execute callback for the count-words ability.
 *
 * @param array $input Validated input matching the input schema.
 * @return int|WP_Error Word count on success, WP_Error on failure.
 */
function wpbp_count_words_ability_execute( $input ) {
	if ( ! is_array( $input ) || ! isset( $input['text'] ) || ! is_string( $input['text'] ) ) {
		return new WP_Error(
			'wpbp_invalid_input',
			__( 'The "text" property is required and must be a string.', 'wpbp' )
		);
	}

	$text = wp_strip_all_tags( $input['text'] );
	$text = html_entity_decode( $text, ENT_QUOTES | ENT_HTML5, 'UTF-8' );
	$text = trim( $text );

	if ( '' === $text ) {
		return 0;
	}

	$words = preg_split( '/[\s\p{Z}]+/u', $text, -1, PREG_SPLIT_NO_EMPTY );

	if ( false === $words ) {
		return count( array_filter( explode( ' ', $text ), 'strlen' ) );
	}

	return count( $words );
}

/**
 * Permission callback for the count-words ability.
 *
 * @return bool
 */
function wpbp_count_words_ability_permission() {
	return current_user_can( 'edit_posts' );
}
