<?php

if ( ! function_exists( 'wpbp_abilities_api_008' ) ) {
	/**
	 * Unregisters an ability and verifies removal.
	 *
	 * @param string $ability_name Ability name.
	 * @return bool True if a WP_Ability instance was returned and the ability no longer exists.
	 */
	function wpbp_abilities_api_008( string $ability_name ): bool {
		if ( ! function_exists( 'wp_unregister_ability' ) || ! function_exists( 'wp_has_ability' ) ) {
			return false;
		}

		$ability_name = trim( $ability_name );

		if ( '' === $ability_name ) {
			return false;
		}

		$result = wp_unregister_ability( $ability_name );

		if ( ! ( $result instanceof WP_Ability ) ) {
			return false;
		}

		return ! wp_has_ability( $ability_name );
	}
}
