<?php

if ( ! function_exists( 'wpbp_abilities_api_011' ) ) {
	/**
	 * Returns the sorted list of registered ability names for a given category slug.
	 *
	 * @param string $category Category slug to filter by.
	 * @return string[] Alphabetically sorted ability names.
	 */
	function wpbp_abilities_api_011( string $category ): array {
		$category = sanitize_key( $category );
		$names    = array();

		if ( '' === $category || ! function_exists( 'wp_get_abilities' ) ) {
			return $names;
		}

		$abilities = wp_get_abilities();

		if ( ! is_array( $abilities ) ) {
			return $names;
		}

		foreach ( $abilities as $ability ) {
			if ( ! is_object( $ability ) ) {
				continue;
			}

			$ability_category = '';
			if ( method_exists( $ability, 'get_category' ) ) {
				$ability_category = (string) $ability->get_category();
			} elseif ( isset( $ability->category ) ) {
				$ability_category = (string) $ability->category;
			}

			if ( $ability_category !== $category ) {
				continue;
			}

			$name = '';
			if ( method_exists( $ability, 'get_name' ) ) {
				$name = (string) $ability->get_name();
			} elseif ( isset( $ability->name ) ) {
				$name = (string) $ability->name;
			}

			if ( '' !== $name ) {
				$names[] = $name;
			}
		}

		$names = array_values( array_unique( $names ) );
		sort( $names, SORT_STRING );

		return $names;
	}
}
