/**
 * Reports whether an ability is registered and whether it is exposed via REST.
 *
 * @param string $ability_name Ability name (e.g. 'my-plugin/do-thing').
 * @return array{registered: bool, show_in_rest: bool}
 */
function wpbp_abilities_api_012( string $ability_name ): array {
	$result = array(
		'registered'   => false,
		'show_in_rest' => false,
	);

	// Gate on existence to avoid the "not registered" notice from wp_get_ability().
	if ( ! function_exists( 'wp_has_ability' ) || ! wp_has_ability( $ability_name ) ) {
		return $result;
	}

	$result['registered'] = true;

	$ability = wp_get_ability( $ability_name );
	if ( ! $ability instanceof WP_Ability ) {
		return $result;
	}

	$meta = $ability->get_meta();
	if ( is_array( $meta ) && array_key_exists( 'show_in_rest', $meta ) ) {
		$result['show_in_rest'] = (bool) $meta['show_in_rest'];
	}

	return $result;
}
