<?php

use WordPress\AiClient\Tools\DTO\FunctionCall;
use WordPress\AiClient\Tools\DTO\FunctionResponse;

/**
 * Executes the supplied AI function call via the ability function resolver,
 * allowing only the 'wpbp/echo-upper' ability, and returns the response payload.
 *
 * @param FunctionCall $function_call The function call issued by the AI model.
 * @return mixed The FunctionResponse payload, or a WP_Error on failure.
 */
function wpbp_ai_client_010( $function_call ) {
	if ( ! class_exists( 'WP_AI_Client_Ability_Function_Resolver' ) ) {
		return new WP_Error(
			'wpbp_ai_client_missing_resolver',
			__( 'The AI Client ability function resolver is not available.', 'wpbp' )
		);
	}

	if ( ! $function_call instanceof FunctionCall ) {
		return new WP_Error(
			'wpbp_ai_client_invalid_function_call',
			__( 'A valid FunctionCall instance is required.', 'wpbp' )
		);
	}

	if ( 'wpbp/echo-upper' !== $function_call->getName() ) {
		return new WP_Error(
			'wpbp_ai_client_ability_not_allowed',
			sprintf(
				/* translators: %s: function/ability name */
				__( 'The ability "%s" is not allowed by this resolver.', 'wpbp' ),
				$function_call->getName()
			)
		);
	}

	$resolver = new WP_AI_Client_Ability_Function_Resolver( array( 'wpbp/echo-upper' ) );

	try {
		$function_response = $resolver->execute_ability( $function_call );
	} catch ( \Throwable $e ) {
		return new WP_Error(
			'wpbp_ai_client_execution_failed',
			$e->getMessage()
		);
	}

	if ( is_wp_error( $function_response ) ) {
		return $function_response;
	}

	if ( ! $function_response instanceof FunctionResponse ) {
		return new WP_Error(
			'wpbp_ai_client_invalid_response',
			__( 'The resolver did not return a valid FunctionResponse.', 'wpbp' )
		);
	}

	return $function_response->getResponse();
}
