<?php
/**
 * Demonstrates distinguishing a cached boolean false from a cache miss
 * using the $found flag of wp_cache_get().
 *
 * @param string $key   Cache key.
 * @param string $group Cache group.
 * @return array{0: mixed, 1: bool, 2: mixed, 3: bool} [ $miss_value, $miss_found, $hit_value, $hit_found ].
 */
function wpbp_caching_001( string $key, string $group ): array {
	// Ensure a clean slate so the first read is a genuine miss.
	wp_cache_delete( $key, $group );

	// First read: should be a miss (value false, found false).
	$miss_found = false;
	$miss_value = wp_cache_get( $key, $group, false, $miss_found );

	// Store boolean false in the cache.
	wp_cache_set( $key, false, $group );

	// Second read: value is still false, but the found flag reports a hit.
	$hit_found = false;
	$hit_value = wp_cache_get( $key, $group, false, $hit_found );

	return array( $miss_value, (bool) $miss_found, $hit_value, (bool) $hit_found );
}
