<?php

function wpbp_caching_006( array $values, array $keys, string $group, array $salt ): array {
	$group = '' !== $group ? $group : 'default';

	if ( ! empty( $values ) ) {
		wp_cache_set_multiple_salted( $values, $salt, $group );
	}

	$stale_salt = $salt;
	$stale_salt['__wpbp_stale_marker'] = 'stale-' . md5( serialize( $salt ) . '|stale' );

	$current_raw = ! empty( $keys ) ? wp_cache_get_multiple_salted( $keys, $salt, $group ) : array();
	$stale_raw   = ! empty( $keys ) ? wp_cache_get_multiple_salted( $keys, $stale_salt, $group ) : array();

	if ( ! is_array( $current_raw ) ) {
		$current_raw = array();
	}
	if ( ! is_array( $stale_raw ) ) {
		$stale_raw = array();
	}

	$current = array();
	$stale   = array();

	foreach ( $keys as $key ) {
		$current[ $key ] = array_key_exists( $key, $current_raw ) ? $current_raw[ $key ] : false;
		$stale[ $key ]   = array_key_exists( $key, $stale_raw ) ? $stale_raw[ $key ] : false;
	}

	return array(
		'current' => $current,
		'stale'   => $stale,
	);
}
