function wpbp_comments_users_001( string $login ): WP_User|WP_Error {
    $login = sanitize_user( $login, true );

    if ( '' === $login ) {
        return new WP_Error( 'invalid_login', 'A valid user login is required.' );
    }

    if ( username_exists( $login ) ) {
        return new WP_Error( 'user_exists', 'A user with that login already exists.' );
    }

    $user_id = wp_insert_user(
        array(
            'user_login' => $login,
            'user_pass'  => wp_generate_password( 24, true, true ),
            'role'       => 'subscriber',
        )
    );

    if ( is_wp_error( $user_id ) ) {
        return $user_id;
    }

    $user = get_user_by( 'id', $user_id );

    if ( ! $user instanceof WP_User ) {
        return new WP_Error( 'user_not_found', 'The user could not be retrieved after creation.' );
    }

    return $user;
}
