<?php

if ( ! function_exists( 'wpbp_connectors_api_002' ) ) {
	/**
	 * Safely retrieve connector data for the given connector ID.
	 *
	 * Checks registration status through the public Connectors API before
	 * attempting retrieval so that no not-found registry notice is triggered.
	 *
	 * @param string $connector_id Connector identifier.
	 * @return array|null Connector data array, or null if the connector is unknown.
	 */
	function wpbp_connectors_api_002( string $connector_id ): ?array {
		$connector_id = trim( $connector_id );

		if ( '' === $connector_id ) {
			return null;
		}

		if ( ! function_exists( 'wp_is_connector_registered' ) || ! function_exists( 'wp_get_connector' ) ) {
			return null;
		}

		if ( ! wp_is_connector_registered( $connector_id ) ) {
			return null;
		}

		$connector = wp_get_connector( $connector_id );

		if ( null === $connector || false === $connector ) {
			return null;
		}

		if ( is_array( $connector ) ) {
			return $connector;
		}

		if ( is_object( $connector ) ) {
			if ( method_exists( $connector, 'to_array' ) ) {
				$data = $connector->to_array();
				return is_array( $data ) ? $data : null;
			}

			return get_object_vars( $connector );
		}

		return null;
	}
}
