<?php

if ( ! function_exists( 'wpbp_connectors_api_013' ) ) {
	/**
	 * Register connector data under the supplied ID only when it is safe to do so.
	 *
	 * @param string $connector_id Connector identifier.
	 * @param array  $args         Connector arguments, must include a valid 'authentication' array.
	 * @return string One of 'exists', 'invalid', or 'registered'.
	 */
	function wpbp_connectors_api_013( string $connector_id, array $args ): string {
		$registry = WP_Connector_Registry::get_instance();

		if ( $registry->is_registered( $connector_id ) ) {
			return 'exists';
		}

		if ( ! isset( $args['authentication'] ) || ! is_array( $args['authentication'] ) ) {
			return 'invalid';
		}

		$authentication = $args['authentication'];

		if ( ! isset( $authentication['method'] ) || ! is_string( $authentication['method'] ) ) {
			return 'invalid';
		}

		$allowed_methods = array( 'api_key', 'none' );

		if ( ! in_array( $authentication['method'], $allowed_methods, true ) ) {
			return 'invalid';
		}

		$registry->register( $connector_id, $args );

		return 'registered';
	}
}
