<?php

function wpbp_gb_block_api_002(): bool {
    if ( ! function_exists( 'register_block_type' ) ) {
        return false;
    }

    $block_name = 'wpbp/auto';

    if ( class_exists( 'WP_Block_Type_Registry' ) && WP_Block_Type_Registry::get_instance()->is_registered( $block_name ) ) {
        return true;
    }

    $args = array(
        'api_version'     => 3,
        'title'           => 'Auto Block',
        'category'        => 'widgets',
        'attributes'      => array(
            'message' => array(
                'type'    => 'string',
                'default' => 'Hi',
            ),
        ),
        'supports'        => array(
            'html' => false,
        ),
        'render_callback' => static function ( array $attributes ): string {
            $message = isset( $attributes['message'] ) && is_string( $attributes['message'] )
                ? $attributes['message']
                : 'Hi';

            return '<p class="wp-block-wpbp-auto">' . esc_html( $message ) . '</p>';
        },
    );

    $block_type = register_block_type( $block_name, $args );

    if ( ! ( $block_type instanceof WP_Block_Type ) ) {
        return false;
    }

    // PHP-only auto-registration: expose the server definition to the editor
    // without shipping a dedicated JS bundle for the block.
    $auto_register = static function () use ( $block_name ): void {
        if ( ! function_exists( 'wp_add_inline_script' ) ) {
            return;
        }

        wp_enqueue_script( 'wp-blocks' );
        wp_enqueue_script( 'wp-element' );
        wp_enqueue_script( 'wp-server-side-render' );
        wp_enqueue_script( 'wp-block-editor' );

        $script = sprintf(
            '( function( wp ) {
                if ( ! wp || ! wp.blocks || wp.blocks.getBlockType( %1$s ) ) { return; }
                var el = wp.element.createElement;
                var ServerSideRender = wp.serverSideRender;
                var useBlockProps = wp.blockEditor.useBlockProps;
                wp.blocks.registerBlockType( %1$s, {
                    edit: function( props ) {
                        return el( "div", useBlockProps(),
                            el( ServerSideRender, { block: %1$s, attributes: props.attributes } )
                        );
                    },
                    save: function() { return null; }
                } );
            } )( window.wp );',
            wp_json_encode( $block_name )
        );

        wp_add_inline_script( 'wp-blocks', $script, 'after' );
    };

    if ( function_exists( 'add_action' ) ) {
        if ( function_exists( 'did_action' ) && did_action( 'enqueue_block_editor_assets' ) ) {
            $auto_register();
        } else {
            add_action( 'enqueue_block_editor_assets', $auto_register );
        }
    }

    return true;
}
