<?php

function wpbp_gb_block_api_006( string $content ): array {
	if ( '' === $content || ! class_exists( 'WP_Block_Processor' ) ) {
		return array();
	}

	$processor = new WP_Block_Processor( $content );
	$openings  = 0;

	while ( $openings < 10 && $processor->next_delimiter() ) {
		if ( ! $processor->opens_block() ) {
			continue;
		}

		$openings++;

		if ( ! $processor->is_block_type( 'core/image' ) ) {
			continue;
		}

		$span = $processor->get_span();
		if ( null === $span ) {
			return array();
		}

		$start = $span->start;
		$end   = $span->start + $span->length;

		// A non-void opener needs its matching closer to capture the full block.
		if ( ! $processor->closes_block() ) {
			$depth = 1;
			$end   = strlen( $content );

			while ( $depth > 0 && $processor->next_delimiter() ) {
				$opens  = $processor->opens_block();
				$closes = $processor->closes_block();

				if ( $opens && ! $closes ) {
					$depth++;
				} elseif ( $closes && ! $opens ) {
					$depth--;
					if ( 0 === $depth ) {
						$closer = $processor->get_span();
						if ( null !== $closer ) {
							$end = $closer->start + $closer->length;
						}
					}
				}
			}
		}

		$blocks = parse_blocks( substr( $content, $start, $end - $start ) );

		foreach ( $blocks as $block ) {
			if ( isset( $block['blockName'] ) && 'core/image' === $block['blockName'] ) {
				return $block;
			}
		}

		return array();
	}

	return array();
}
