/**
 * Hook 'wpbp/context-note' as the first child of core/group blocks,
 * but only when the Block Hooks context is a pattern array whose slug is 'wpbp-pattern'.
 */
function wpbp_gb_block_hooks_002(): void {
	add_filter(
		'hooked_block_types',
		/**
		 * @param string[]                                 $hooked_block_types Block types currently hooked at this position.
		 * @param string                                   $relative_position  One of 'before', 'after', 'first_child', 'last_child'.
		 * @param string|null                              $anchor_block_type  The anchor block type (null for root-level positions).
		 * @param WP_Block_Template|WP_Post|array|null     $context            Template, post, or pattern array providing context.
		 * @return string[]
		 */
		static function ( $hooked_block_types, $relative_position, $anchor_block_type, $context ) {
			if ( ! is_array( $hooked_block_types ) ) {
				$hooked_block_types = array();
			}

			// Only target the first child position of core/group blocks.
			if ( 'first_child' !== $relative_position || 'core/group' !== $anchor_block_type ) {
				return $hooked_block_types;
			}

			// Only apply when the context is a pattern array with the expected slug.
			if ( ! is_array( $context ) ) {
				return $hooked_block_types;
			}

			$slug = $context['slug'] ?? null;
			if ( 'wpbp-pattern' !== $slug ) {
				return $hooked_block_types;
			}

			// Preserve existing hooked block types and avoid duplicates.
			if ( ! in_array( 'wpbp/context-note', $hooked_block_types, true ) ) {
				$hooked_block_types[] = 'wpbp/context-note';
			}

			return $hooked_block_types;
		},
		10,
		4
	);
}
