<?php

function wpbp_gb_markup_008(): string {
	$rows = array(
		'head' => array(
			array( 'Plan', 'Price' ),
		),
		'body' => array(
			array( 'Basic', '$10' ),
			array( 'Pro', '$20' ),
		),
	);

	$render_section = static function ( string $section, array $section_rows ): string {
		$tag_section = 't' . $section;
		$cell_tag    = ( 'head' === $section ) ? 'th' : 'td';
		$html        = '<' . $tag_section . '>';

		foreach ( $section_rows as $cells ) {
			$html .= '<tr>';
			foreach ( $cells as $cell ) {
				$html .= '<' . $cell_tag . '>' . $cell . '</' . $cell_tag . '>';
			}
			$html .= '</tr>';
		}

		$html .= '</' . $tag_section . '>';

		return $html;
	};

	$table  = '<table class="has-fixed-layout">';
	$table .= $render_section( 'head', $rows['head'] );
	$table .= $render_section( 'body', $rows['body'] );
	$table .= '</table>';

	$markup  = "<!-- wp:table -->\n";
	$markup .= '<figure class="wp-block-table">' . $table . '</figure>' . "\n";
	$markup .= '<!-- /wp:table -->';

	return $markup;
}
