<?php

/**
 * Returns a safe Interactivity API context attribute for the supplied
 * context data in the 'wpbp/store' namespace.
 *
 * @param array $context Context data to expose to the Interactivity API.
 * @return string The complete data-wp-context attribute string.
 */
function wpbp_gb_interactivity_api_002( array $context ): string {
	$namespace = 'wpbp/store';

	if ( function_exists( 'wp_interactivity_data_wp_context' ) ) {
		return wp_interactivity_data_wp_context( $context, $namespace );
	}

	// Fallback for environments where the Interactivity API helper is unavailable.
	$json = wp_json_encode(
		$context,
		JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP | JSON_UNESCAPED_SLASHES
	);

	if ( false === $json ) {
		$json = '{}';
	}

	return 'data-wp-context=\'' . $namespace . '::' . $json . '\'';
}
