<?php

if ( ! function_exists( 'wpbp_gb_interactivity_api_003' ) ) {
	/**
	 * Registers derived Interactivity API state for the 'wpbp/iapi-derived'
	 * namespace and processes the supplied HTML with the directive processor.
	 *
	 * @param string $html Markup containing Interactivity API directives.
	 * @return string Server-processed markup.
	 */
	function wpbp_gb_interactivity_api_003( string $html ): string {
		$namespace = 'wpbp/iapi-derived';

		if ( ! function_exists( 'wp_interactivity_state' ) || ! function_exists( 'wp_interactivity_process_directives' ) ) {
			return $html;
		}

		wp_interactivity_state(
			$namespace,
			array(
				'items'   => array( 'Alpha', 'Beta', 'Gamma' ),
				'count'   => 3,
				'summary' => function () use ( $namespace ): string {
					$state = wp_interactivity_state( $namespace );
					$items = isset( $state['items'] ) && is_array( $state['items'] ) ? $state['items'] : array();
					$count = isset( $state['count'] ) ? (int) $state['count'] : count( $items );

					return sprintf(
						'%d item%s: %s',
						$count,
						1 === $count ? '' : 's',
						implode( ', ', array_map( 'strval', $items ) )
					);
				},
			)
		);

		return wp_interactivity_process_directives( $html );
	}
}
