<?php
/**
 * Returns server-processed markup for a single interactive element on which
 * two independent plugins toggle the same `active` class using unique
 * Interactivity API directive IDs (triple-dash suffix).
 *
 * @return string Processed HTML markup.
 */
function wpbp_gb_interactivity_api_004(): string {
	$namespace = 'wpbp/iapi-unique';

	// Global state consumed by both "plugins" through the same namespace.
	if ( function_exists( 'wp_interactivity_state' ) ) {
		wp_interactivity_state(
			$namespace,
			array(
				'pluginAIsActive' => true,
				'pluginBIsActive' => false,
			)
		);
	}

	$context = function_exists( 'wp_interactivity_data_wp_context' )
		? wp_interactivity_data_wp_context(
			array(
				'pluginAIsActive' => true,
				'pluginBIsActive' => false,
			),
			$namespace
		)
		: sprintf(
			'data-wp-context=\'%s\'',
			wp_json_encode(
				array(
					'pluginAIsActive' => true,
					'pluginBIsActive' => false,
				)
			)
		);

	$markup = sprintf(
		'<div data-wp-interactive="%1$s" %2$s>' .
			'<button ' .
				'type="button" ' .
				'class="wpbp-toggle" ' .
				'data-wp-class--active---plugin-a="context.pluginAIsActive" ' .
				'data-wp-class--active---plugin-b="context.pluginBIsActive" ' .
				'data-wp-on--click---plugin-a="actions.togglePluginA" ' .
				'data-wp-on--click---plugin-b="actions.togglePluginB"' .
			'>Toggle</button>' .
		'</div>',
		esc_attr( $namespace ),
		$context
	);

	if ( function_exists( 'wp_interactivity_process_directives' ) ) {
		return wp_interactivity_process_directives( $markup );
	}

	return $markup;
}
