<?php

if ( ! function_exists( 'wpbp_gb_templates_navigation_002' ) ) {
	/**
	 * Render a core/navigation-link block for a given URL and label.
	 *
	 * @param string $url   The link URL.
	 * @param string $label The link label.
	 * @return string Rendered block markup.
	 */
	function wpbp_gb_templates_navigation_002( string $url, string $label ): string {
		if ( ! function_exists( 'render_block' ) ) {
			return '';
		}

		$url   = esc_url_raw( $url );
		$label = wp_strip_all_tags( $label );

		$attributes = array(
			'label' => $label,
			'url'   => $url,
			'kind'  => 'custom',
		);

		$block = array(
			'blockName'    => 'core/navigation-link',
			'attrs'        => $attributes,
			'innerBlocks'  => array(),
			'innerHTML'    => '',
			'innerContent' => array(),
		);

		$rendered = render_block( $block );

		if ( '' === trim( (string) $rendered ) ) {
			$serialized = '<!-- wp:navigation-link ' . wp_json_encode( $attributes ) . ' /-->';
			$rendered   = do_blocks( $serialized );
		}

		return (string) $rendered;
	}
}
