<?php

/**
 * Sanitize a URL for storage or redirects, preferring HTTPS when a scheme is missing.
 *
 * @param string $url Raw URL.
 * @return string Sanitized URL, or empty string if invalid.
 */
function wpbp_mail_url_001( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	$allowed_protocols = array( 'https', 'http' );

	// Detect whether the original input already carried a scheme (or was relative/protocol-relative).
	$has_scheme = (bool) preg_match( '#^[a-z][a-z0-9+.\-]*:#i', $url );
	$is_relative = ( 0 === strpos( $url, '/' ) || 0 === strpos( $url, '#' ) || 0 === strpos( $url, '?' ) );

	// If no scheme was supplied and it is not relative, WordPress would add http:// - we prefer https:// instead.
	if ( ! $has_scheme && ! $is_relative ) {
		$url = 'https://' . ltrim( $url, '/' );
	}

	$sanitized = esc_url_raw( $url, $allowed_protocols );

	if ( '' === $sanitized ) {
		return '';
	}

	// Ensure protocol-relative URLs are also normalized to https where appropriate.
	if ( 0 === strpos( $sanitized, '//' ) ) {
		$sanitized = set_url_scheme( $sanitized, 'https' );
	}

	return $sanitized;
}
