<?php

function wpbp_mail_url_003( string $location ): string {
	if ( '' === $location ) {
		return '';
	}

	if ( function_exists( 'wp_sanitize_redirect' ) ) {
		$sanitized = wp_sanitize_redirect( $location );
	} else {
		// Fallback mirroring wp_sanitize_redirect() behavior when WordPress is not loaded.
		$sanitized = preg_replace_callback(
			'/[^a-z0-9\x{0080}-\x{FFFF}\/\?\#\&\=\.\:\-\_\+\@\%\'\!\*\(\);,~\[\]\|\$]+/iu',
			static function ( $matches ) {
				return rawurlencode( $matches[0] );
			},
			$location
		);

		$sanitized = (string) preg_replace( '|[^a-z0-9-~+_.?#=&;,/:%!*\[\]()@]|i', '', $sanitized );
	}

	if ( ! is_string( $sanitized ) ) {
		return '';
	}

	return $sanitized;
}
