<?php
/**
 * Retrieve WordPress image source data for an attachment.
 *
 * @param int          $attachment_id Attachment post ID.
 * @param string|array $size          Registered image size name or array of width and height values.
 * @return array|false Array of image data (URL, width, height, is_intermediate) or false on failure.
 */
function wpbp_media_001( int $attachment_id, $size = 'thumbnail' ) {
    if ( $attachment_id <= 0 ) {
        return false;
    }

    if ( ! wp_attachment_is_image( $attachment_id ) ) {
        return false;
    }

    $image_src = wp_get_attachment_image_src( $attachment_id, $size );

    if ( ! is_array( $image_src ) || empty( $image_src[0] ) ) {
        return false;
    }

    return $image_src;
}
