<?php

/**
 * Delete only the post meta entries for a given key whose stored value
 * matches the supplied value. Non-matching values for the same key are kept.
 *
 * @param int    $post_id  Post ID.
 * @param string $meta_key Meta key.
 * @param string $value    Value that must match for deletion.
 *
 * @return bool True on success, false on failure or if nothing was deleted.
 */
function wpbp_post_meta_003( int $post_id, string $meta_key, string $value ): bool {
	if ( $post_id <= 0 || '' === $meta_key ) {
		return false;
	}

	if ( ! function_exists( 'delete_post_meta' ) || ! function_exists( 'get_post_meta' ) ) {
		return false;
	}

	// Ensure there is at least one matching entry before attempting deletion.
	$existing = get_post_meta( $post_id, $meta_key, false );

	if ( empty( $existing ) || ! is_array( $existing ) ) {
		return false;
	}

	$has_match = false;
	foreach ( $existing as $stored ) {
		if ( is_scalar( $stored ) && (string) $stored === $value ) {
			$has_match = true;
			break;
		}
	}

	if ( ! $has_match ) {
		return false;
	}

	// Passing a non-empty value makes WordPress delete only rows matching that value.
	return (bool) delete_post_meta( $post_id, $meta_key, $value );
}
