 */
function wpbp_post_types_taxonomy_004(): array
{
    $post_type = 'wpbp_project';
    $singular  = 'project';
    $plural    = 'projects';

    // Meta capabilities that WordPress resolves at runtime through map_meta_cap().
    $meta_caps = [
        'edit_post'   => 'edit_' . $singular,
        'read_post'   => 'read_' . $singular,
        'delete_post' => 'delete_' . $singular,
    ];

    // Primitive capabilities that the meta caps are mapped onto.
    $primitive_caps = [
        'edit_posts'             => 'edit_' . $plural,
        'edit_others_posts'      => 'edit_others_' . $plural,
        'edit_published_posts'   => 'edit_published_' . $plural,
        'edit_private_posts'     => 'edit_private_' . $plural,
        'publish_posts'          => 'publish_' . $plural,
        'read_private_posts'     => 'read_private_' . $plural,
        'delete_posts'           => 'delete_' . $plural,
        'delete_others_posts'    => 'delete_others_' . $plural,
        'delete_published_posts' => 'delete_published_' . $plural,
        'delete_private_posts'   => 'delete_private_' . $plural,
        'create_posts'           => 'create_' . $plural,
    ];

    $capabilities = array_merge($meta_caps, $primitive_caps);

    $result = [
        'post_type'      => $post_type,
        'registered'     => false,
        'unregistered'   => false,
        'meta_caps'      => $meta_caps,
        'primitive_caps' => $primitive_caps,
        'capabilities'   => [],
        'map_meta_cap'   => true,
        'errors'         => [],
    ];

    if (!function_exists('register_post_type')) {
        $result['errors'][] = 'register_post_type() is not available.';
        return $result;
    }

    $args = [
        'label'           => 'Projects',
        'labels'          => [
            'name'          => 'Projects',
            'singular_name' => 'Project',
            'add_new_item'  => 'Add New Project',
            'edit_item'     => 'Edit Project',
            'new_item'      => 'New Project',
            'view_item'     => 'View Project',
            'search_items'  => 'Search Projects',
            'not_found'     => 'No projects found',
        ],
        'public'          => true,
        'show_ui'         => true,
        'show_in_rest'    => true,
        'capability_type' => [$singular, $plural],
        'capabilities'    => $capabilities,
        'map_meta_cap'    => true,
        'supports'        => ['title', 'editor', 'author', 'revisions'],
        'has_archive'     => true,
        'rewrite'         => ['slug' => $plural],
    ];

    $registered = register_post_type($post_type, $args);

    if (function_exists('is_wp_error') && is_wp_error($registered)) {
        $result['errors'][] = $registered->get_error_message();
        return $result;
    }

    $result['registered'] = true;

    if (is_object($registered) && isset($registered->cap)) {
        $result['capabilities'] = (array) $registered->cap;
        $result['map_meta_cap'] = !empty($registered->map_meta_cap);
    } elseif (function_exists('get_post_type_object')) {
        $object = get_post_type_object($post_type);
        if ($object && isset($object->cap)) {
            $result['capabilities'] = (array) $object->cap;
            $result['map_meta_cap'] = !empty($object->map_meta_cap);
        }
    }

    // Verify that each meta cap is mapped to the intended custom capability.
    $result['meta_cap_mapping_verified'] = true;
    foreach ($meta_caps as $meta_cap => $expected) {
        if (!isset($result['capabilities'][$meta_cap]) || $result['capabilities'][$meta_cap] !== $expected) {
            $result['meta_cap_mapping_verified'] = false;
            $result['errors'][] = sprintf('Meta cap "%s" was not mapped to "%s".', $meta_cap, $expected);
        }
    }

    // Clean up: remove the registered post type when the API allows it.
    if (function_exists('unregister_post_type')) {
        $unregistered = unregister_post_type($post_type);
        if (function_exists('is_wp_error') && is_wp_error($unregistered)) {
            $result['errors'][] = $unregistered->get_error_message();
        } else {
            $result['unregistered'] = (bool) $unregistered;
        }
    }

    return $result;
}
