function wpbp_post_types_taxonomy_005( string $name ): array {
	$post_type = 'wpbp_pt_005';
	$taxonomy  = 'wpbp_tax_005';
	$result    = array(
		'slug'     => '',
		'taxonomy' => $taxonomy,
	);

	$registered_post_type = false;
	$registered_taxonomy  = false;

	if ( ! post_type_exists( $post_type ) ) {
		$pt = register_post_type(
			$post_type,
			array(
				'public'  => false,
				'label'   => 'WPBP Post Type 005',
				'show_ui' => false,
			)
		);
		$registered_post_type = ! is_wp_error( $pt );
	}

	if ( ! taxonomy_exists( $taxonomy ) ) {
		$tax = register_taxonomy(
			$taxonomy,
			array( $post_type ),
			array(
				'public'       => false,
				'label'        => 'WPBP Taxonomy 005',
				'hierarchical' => false,
				'show_ui'      => false,
			)
		);
		$registered_taxonomy = ! is_wp_error( $tax );
	}

	$term_name = trim( $name );
	if ( '' !== $term_name && taxonomy_exists( $taxonomy ) ) {
		$existing = term_exists( $term_name, $taxonomy );
		$term_id  = 0;

		if ( $existing ) {
			$term_id = is_array( $existing ) ? (int) $existing['term_id'] : (int) $existing;
		} else {
			$inserted = wp_insert_term( $term_name, $taxonomy );
			if ( ! is_wp_error( $inserted ) && isset( $inserted['term_id'] ) ) {
				$term_id = (int) $inserted['term_id'];
			}
		}

		if ( $term_id > 0 ) {
			$term = get_term( $term_id, $taxonomy );
			if ( $term instanceof WP_Term ) {
				$result['slug']     = $term->slug;
				$result['taxonomy'] = $term->taxonomy;
			}
		}
	}

	if ( $registered_taxonomy && function_exists( 'unregister_taxonomy' ) ) {
		unregister_taxonomy( $taxonomy );
	}

	if ( $registered_post_type && function_exists( 'unregister_post_type' ) ) {
		unregister_post_type( $post_type );
	}

	return $result;
}
