function wpbp_post_types_taxonomy_008(): string {
    $taxonomy    = 'wpbp_genre_008';
    $object_type = 'post';
    $rest_base   = 'wpbp-genres';

    // Avoid double registration if the taxonomy already exists.
    if ( taxonomy_exists( $taxonomy ) ) {
        unregister_taxonomy( $taxonomy );
    }

    $labels = array(
        'name'          => _x( 'Genres', 'taxonomy general name', 'wpbp' ),
        'singular_name' => _x( 'Genre', 'taxonomy singular name', 'wpbp' ),
        'search_items'  => __( 'Search Genres', 'wpbp' ),
        'all_items'     => __( 'All Genres', 'wpbp' ),
        'edit_item'     => __( 'Edit Genre', 'wpbp' ),
        'update_item'   => __( 'Update Genre', 'wpbp' ),
        'add_new_item'  => __( 'Add New Genre', 'wpbp' ),
        'new_item_name' => __( 'New Genre Name', 'wpbp' ),
        'menu_name'     => __( 'Genres', 'wpbp' ),
    );

    $args = array(
        'labels'                => $labels,
        'public'                => true,
        'hierarchical'          => true,
        'show_ui'               => true,
        'show_admin_column'     => true,
        'show_in_rest'          => true,
        'rest_base'             => $rest_base,
        'rest_controller_class' => 'WP_REST_Terms_Controller',
        'query_var'             => true,
        'rewrite'               => array( 'slug' => 'genre' ),
    );

    $result = register_taxonomy( $taxonomy, $object_type, $args );

    if ( is_wp_error( $result ) ) {
        return 'Error: ' . $result->get_error_message();
    }

    $tax_object = get_taxonomy( $taxonomy );

    if ( ! $tax_object ) {
        return 'Error: taxonomy registration failed.';
    }

    $message = sprintf(
        'Registered taxonomy "%s" for "%s" with REST base "%s".',
        $tax_object->name,
        $object_type,
        $tax_object->rest_base
    );

    // Clean up: remove the registered taxonomy so it does not persist.
    $unregistered = unregister_taxonomy( $taxonomy );

    if ( is_wp_error( $unregistered ) ) {
        $message .= ' Cleanup failed: ' . $unregistered->get_error_message();
    } else {
        $message .= ' Taxonomy unregistered.';
    }

    return $message;
}
