	exit;
}

add_action( 'rest_api_init', 'wpbp_register_books_route' );

/**
 * Register the books REST route.
 *
 * @return void
 */
function wpbp_register_books_route() {
	register_rest_route(
		'wpbp/v1',
		'/books/(?P<id>\d+)',
		array(
			'methods'             => WP_REST_Server::READABLE,
			'callback'            => 'wpbp_get_book',
			'permission_callback' => '__return_true',
			'args'                => array(
				'id' => array(
					'description'       => 'Numeric ID of the book.',
					'type'              => 'integer',
					'required'          => true,
					'validate_callback' => 'wpbp_validate_book_id',
					'sanitize_callback' => 'absint',
				),
			),
		)
	);
}

/**
 * Validate that the ID parameter is numeric.
 *
 * @param mixed           $value   The parameter value.
 * @param WP_REST_Request $request The request object.
 * @param string          $param   The parameter name.
 * @return true|WP_Error
 */
function wpbp_validate_book_id( $value, $request, $param ) {
	if ( ! is_numeric( $value ) ) {
		return new WP_Error(
			'rest_invalid_param',
			sprintf( 'The %s parameter must be numeric.', $param ),
			array( 'status' => 400 )
		);
	}

	return true;
}

/**
 * Return the book ID as an integer.
 *
 * @param WP_REST_Request $request The request object.
 * @return WP_REST_Response
 */
function wpbp_get_book( WP_REST_Request $request ) {
	$id = (int) $request->get_param( 'id' );

	return rest_ensure_response(
		array(
			'id' => $id,
		)
	);
}
