declare( strict_types=1 );

if ( ! function_exists( 'wpbp_rewrite_permalinks_001' ) ) {
	/**
	 * Registers an extra permalink structure for items under items/<item-slug>
	 * using the %wpbp_item% rewrite tag.
	 *
	 * Rewrite rules are intentionally not flushed here; flushing should happen
	 * only on plugin activation / deactivation.
	 */
	function wpbp_rewrite_permalinks_001(): void {
		global $wp;

		// Register the rewrite tag and map it to the wpbp_item query var.
		add_rewrite_tag( '%wpbp_item%', '([^/]+)', 'wpbp_item=' );

		// Explicitly register the public query variable.
		if ( $wp instanceof WP ) {
			$wp->add_query_var( 'wpbp_item' );
		}

		add_filter(
			'query_vars',
			static function ( array $vars ): array {
				if ( ! in_array( 'wpbp_item', $vars, true ) ) {
					$vars[] = 'wpbp_item';
				}
				return $vars;
			}
		);

		// Register the extra permalink structure: items/<item-slug>.
		add_permastruct(
			'wpbp_item',
			'items/%wpbp_item%',
			array(
				'with_front'  => false,
				'ep_mask'     => EP_PERMALINK,
				'paged'       => false,
				'feed'        => false,
				'forcomments' => false,
				'walk_dirs'   => false,
				'endpoints'   => true,
			)
		);
	}
}

add_action( 'init', 'wpbp_rewrite_permalinks_001' );
