<?php

function wpbp_roles_caps_001(): bool {
    $role_name = 'wpbp_manager';

    if ( ! function_exists( 'add_role' ) || ! function_exists( 'get_role' ) ) {
        return false;
    }

    // Remove any stale definition so the capability set is exactly what we expect.
    if ( get_role( $role_name ) ) {
        remove_role( $role_name );
    }

    $role = add_role(
        $role_name,
        __( 'WPBP Manager', 'wpbp' ),
        array(
            'read'        => true,
            'wpbp_manage' => true,
        )
    );

    if ( ! ( $role instanceof WP_Role ) ) {
        return false;
    }

    $fetched = get_role( $role_name );

    if ( ! ( $fetched instanceof WP_Role ) ) {
        return false;
    }

    if ( ! $fetched->has_cap( 'read' ) || ! $fetched->has_cap( 'wpbp_manage' ) ) {
        return false;
    }

    $roles = wp_roles();

    if ( ! $roles instanceof WP_Roles || ! $roles->is_role( $role_name ) ) {
        return false;
    }

    return true;
}
