<?php

/**
 * Allow the Editor role to appear in the "New User Default Role" dropdown
 * while keeping Administrator excluded.
 */
function wpbp_roles_caps_006(): void {
	add_filter(
		'default_role_excluded_roles',
		static function ( $excluded_roles ): array {
			if ( ! is_array( $excluded_roles ) ) {
				$excluded_roles = array();
			}

			// Remove "editor" from the exclusion list so it becomes selectable.
			$excluded_roles = array_values(
				array_filter(
					$excluded_roles,
					static function ( $role ): bool {
						return 'editor' !== $role;
					}
				)
			);

			// Ensure "administrator" always remains excluded.
			if ( ! in_array( 'administrator', $excluded_roles, true ) ) {
				$excluded_roles[] = 'administrator';
			}

			return $excluded_roles;
		},
		10,
		1
	);
}
