<?php
/**
 * Check whether a specific user has a given capability without altering the current user.
 *
 * @param int    $user_id User ID to check.
 * @param string $cap     Capability (or role name) to test for.
 * @return bool True if the user has the capability, false otherwise.
 */
function wpbp_roles_caps_007( int $user_id, string $cap ): bool {
	if ( $user_id <= 0 || '' === $cap ) {
		return false;
	}

	if ( function_exists( 'user_can' ) ) {
		return (bool) user_can( $user_id, $cap );
	}

	$user = get_userdata( $user_id );

	if ( ! $user instanceof WP_User || ! $user->exists() ) {
		return false;
	}

	return (bool) $user->has_cap( $cap );
}
