<?php

/**
 * Filter a chunk of post content so only HTML allowed for WordPress
 * post content remains.
 *
 * @param string $html Raw HTML to be filtered.
 * @return string Filtered HTML safe for post content.
 */
function wpbp_security_003( string $html ): string {
	if ( '' === $html ) {
		return '';
	}

	if ( function_exists( 'wp_kses_post' ) ) {
		return (string) wp_kses_post( $html );
	}

	if ( function_exists( 'wp_kses' ) && function_exists( 'wp_kses_allowed_html' ) ) {
		return (string) wp_kses( $html, wp_kses_allowed_html( 'post' ) );
	}

	// Fallback when WordPress KSES functions are unavailable.
	return strip_tags( $html );
}
