<?php

function wpbp_security_005( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	$allowed_protocols = array( 'https', 'http' );

	// Detect a missing scheme the same way esc_url() does, but prefer HTTPS.
	$has_scheme   = (bool) preg_match( '#^[a-zA-Z][a-zA-Z0-9+.\-]*:#', $url );
	$is_relative  = ( 0 === strpos( $url, '/' ) )
		|| ( 0 === strpos( $url, '#' ) )
		|| ( 0 === strpos( $url, '?' ) );
	$is_protocol_relative = ( 0 === strpos( $url, '//' ) );

	if ( $is_protocol_relative ) {
		$url = 'https:' . $url;
	} elseif ( ! $has_scheme && ! $is_relative ) {
		$url = 'https://' . $url;
	}

	return (string) esc_url( $url, $allowed_protocols, 'display' );
}
